/// <summary>
/// DebuC 30.03.23
/// </summary>
final class NDXIntrastat
{
    date     filterFromDate;
    date     filterToDate;
    NDXMonat   filterMonat;
    NDXJahr    filterJahr;
    TaxCode    taxCode;
    TaxCode    taxCode2;                                                        

    PurchId purchId;
    ItemId itemId;
    InventTransId inventTransId;

}

Method.Source:
/// <summary>
/// DebuC 30.03.23
/// </summary>
void checkDiff()
{
    NDXIntrastatDiff           nDXIntrastatDiff;
    NDXIntrastatDiffLine       nDXIntrastatDiffLine;
    NDXVendPackingSlipTrans    nDXVendPackingSlipTrans;
    NDXVendInvoiceTrans        nDXVendInvoiceTrans;
    VendInvoiceTrans            vendInvoiceTrans;
    VendPackingSlipTrans        vendPackingSlipTrans;
    VendPackingSlipJour         vendPackingSlipJour;
    InventTable                 inventTable;
    MarkupTrans                 markupTrans;
    TaxTrans    taxTrans, taxTrans2;
    Intrastat   intraStat;
    boolean     lWithMarkupValue;
    int         x;
    boolean     lVendInvoiceTrans;
    boolean     lInvoiceBase;
    NDXIntrastat   nDXIntrastat = new NDXIntrastat();
    str         qValue;

    Query                   q, q2;
    QueryRun                qr, qr2;
    QueryBuildDataSource    qbds, qbds2, qbds4, qbds5;
    ;
    select firstonly forUpdate nDXIntrastatDiff
    where   nDXIntrastatDiff.Monat == filterMonat
        &&  nDXIntrastatDiff.Jahr == filterJahr;
    if (!nDXIntrastatDiff)
    {
        nDXIntrastatDiff.Jahr  = filterJahr;
        nDXIntrastatDiff.Monat = filterMonat;
    }

    delete_from nDXIntrastatDiffLine
    where   nDXIntrastatDiffLine.Monat == filterMonat
        &&  nDXIntrastatDiffLine.Jahr  == filterJahr;

    // Ermittlung der Werte gemäß: taxTrans
    q = new Query();
    q.allowCrossCompany(true);
    qbds = q.addDataSource(tablenum(TaxTrans));
    qbds.addRange(fieldnum(TaxTrans, TransDate)).value(SysQuery::range(filterFromDate, filterToDate));
    qbds.addRange(fieldnum(TaxTrans, InventTransId)).value(SysQuery::valueNotEmptyString());

    if (taxCode && taxCode2)
    {
        qValue = strfmt('((%1 == "%2") || (%1 == "%3"))', fieldid2name(tablenum(TaxTrans), fieldnum(TaxTrans, TaxCode)),taxCode, taxCode2);
    }
    else if (taxCode2)
    {
        qValue = QueryValue(taxCode2);
    }
    else
    {
        qValue = QueryValue(taxCode);
    }
    qbds.addRange(fieldnum(TaxTrans, TaxCode)).value(qValue);

    qr = new QueryRun(q);
    while (qr.next())
    {
        taxTrans = qr.get(tablenum(TaxTrans));

        changecompany(taxTrans.dataAreaId)
        {

            vendInvoiceTrans = null;
            markupTrans = null;
            taxTrans2 = null;
            inventTable = null;
            intraStat = null;

            while select vendInvoiceTrans
            where   vendInvoiceTrans.InventTransId == taxTrans.InventTransId
            {
                lWithMarkupValue = true;
                select sum(Value) from markupTrans
                where markupTrans.TransTableId == tablenum(VendInvoiceTrans)
                    && markupTrans.dataAreaId == vendInvoiceTrans.dataAreaId
                    && markupTrans.TransRecId == vendInvoiceTrans.RecId;
                if (markupTrans.Value)
                {
                    // Falls der Zuschlags-Wert bereits als TaxTrans-DS vorhanden ist, diesen nicht mit einbeziehen
                    select firstonly taxTrans2
                    where   taxTrans2.InventTransId == taxTrans.InventTransId
                        &&  taxTrans2.SourceBaseAmountCur == markupTrans.Value;
                    lWithMarkupValue = false;
                }
                if ((vendInvoiceTrans.LineAmount + (lWithMarkupValue ? markupTrans.Value : 0)) == taxtrans.SourceBaseAmountCur)
                {
                    break;
                }
            }
            if (!vendInvoiceTrans)
            {
                x = 1;
                continue;
            }

            select firstonly inventTable
            where   inventTable.ItemId == vendInvoiceTrans.ItemId;

            // Rechnungs-Lieferschein-Positions-Zuordnung ermitteln
            {
                nDXIntrastat.initialize(vendInvoiceTrans.OrigPurchId, vendInvoiceTrans.ItemId, vendInvoiceTrans.InventTransId);
                nDXIntrastat.VendPackingSlipTrans4PurchLineItem();
                nDXIntrastat.VendInvoiceTrans4PurchLineItem();
                nDXIntrastat.VendPackingSlip2VendInvoice();
            }

            // wurde Intrastat-Buchung gem. Rechnungsposition ermittelt?
            select firstonly intraStat
            where   intraStat.dataAreaId == taxTrans.dataAreaId
                &&  intraStat.InventTransId == taxTrans.InventTransId
                &&  intraStat.TransTableId == tablenum(vendInvoiceTrans)
                &&  intraStat.TransRecId == vendInvoiceTrans.RecId
                &&  intraStat.TransDate == vendInvoiceTrans.InvoiceDate;
            lInvoiceBase = intraStat != null;


            q2 = new Query();
            if (lInvoiceBase)
            {
                qbds5 = q2.addDataSource(tablenum(NDXVendInvoiceTrans));
                qbds5.addRange(fieldnum(NDXVendInvoiceTrans, dataAreaId)).value(vendInvoiceTrans.dataAreaId);
                qbds5.addRange(fieldnum(NDXVendInvoiceTrans, OrigPurchid)).value(vendInvoiceTrans.OrigPurchId);
                qbds5.addRange(fieldnum(NDXVendInvoiceTrans, ItemId)).value(vendInvoiceTrans.ItemId);
                qbds5.addRange(fieldnum(NDXVendInvoiceTrans, InventTransId)).value(vendInvoiceTrans.InventTransId);
                qbds5.addRange(fieldnum(NDXVendInvoiceTrans, InvoiceDate)).value(SysQuery::range(filterFromDate, filterToDate));
                qbds5.addRange(fieldnum(NDXVendInvoiceTrans, RefRecIdVendInvoiceTrans)).value(QueryValue(vendInvoiceTrans.RecId));
            }
            else
            {
                qbds5 = q2.addDataSource(tablenum(NDXVendPackingSlipTrans));
                qbds5.addRange(fieldnum(NDXVendPackingSlipTrans, dataAreaId)).value(vendInvoiceTrans.dataAreaId);
                qbds5.addRange(fieldnum(NDXVendPackingSlipTrans, OrigPurchid)).value(vendInvoiceTrans.OrigPurchId);
                qbds5.addRange(fieldnum(NDXVendPackingSlipTrans, ItemId)).value(vendInvoiceTrans.ItemId);
                qbds5.addRange(fieldnum(NDXVendPackingSlipTrans, InventTransId)).value(vendInvoiceTrans.InventTransId);
                qbds5.addRange(fieldnum(NDXVendPackingSlipTrans, DeliveryDate)).value(SysQuery::range(filterFromDate, filterToDate));
                qbds5.addRange(fieldnum(NDXVendPackingSlipTrans, RefRecIdVendInvoiceTrans)).value(QueryValue(vendInvoiceTrans.RecId));
            }
            qr2 = new QueryRun(q2);
            while (qr2.next())
            {
                if (lInvoiceBase)
                {
                    nDXVendInvoiceTrans = qr2.get(tablenum(NDXVendInvoiceTrans));
                    select firstonly forUpdate nDXIntrastatDiffLine
                    where   nDXIntrastatDiffLine.Jahr == filterJahr
                        &&  nDXIntrastatDiffLine.Monat == filterMonat
                        &&  nDXIntrastatDiffLine.RefCompanyId == taxTrans.dataAreaId
                        &&  nDXIntrastatDiffLine.RefRecIdTaxTrans == taxTrans.RecId
                        &&  nDXIntrastatDiffLine.RefRecIdVendInvoiceTrans == NDXVendInvoiceTrans.RefRecIdVendInvoiceTrans;
                }
                else
                {
                    nDXVendPackingSlipTrans = qr2.get(tablenum(NDXVendPackingSlipTrans));
                    select firstonly forUpdate nDXIntrastatDiffLine
                    where   nDXIntrastatDiffLine.Jahr == filterJahr
                        &&  nDXIntrastatDiffLine.Monat == filterMonat
                        &&  nDXIntrastatDiffLine.RefCompanyId == taxTrans.dataAreaId
                        &&  nDXIntrastatDiffLine.RefRecIdTaxTrans == taxTrans.RecId
                        &&  nDXIntrastatDiffLine.RefRecIdVendPackingSlipTrans == nDXVendPackingSlipTrans.RefRecIdVendPackingSlipTrans;
                }

                if (!nDXIntrastatDiffLine)
                {
                    nDXIntrastatDiffLine.RefCompanyId      = taxTrans.dataAreaId;
                    nDXIntrastatDiffLine.RefRecIdTaxTrans  = taxTrans.RecId;
                    nDXIntrastatDiffLine.RefRecIdVendInvoiceTrans  = vendInvoiceTrans.RecId;
                    if (lInvoiceBase)
                    {
                        nDXIntrastatDiffLine.RefRecIdVendInvoiceTrans = nDXVendInvoiceTrans.RefRecIdVendInvoiceTrans;
                        nDXIntrastatDiffLine.AccountNum               = nDXVendInvoiceTrans.AccountNum;
                        nDXIntrastatDiffLine.CountryRegionIdVendPackingSlipTrans = nDXVendInvoiceTrans.CountryRegionIdVendInvoiceTrans;
                    }
                    else
                    {
                        nDXIntrastatDiffLine.RefRecIdVendPackingSlipTrans = nDXVendPackingSlipTrans.RefRecIdVendPackingSlipTrans;
                        nDXIntrastatDiffLine.AccountNum        = nDXVendPackingSlipTrans.AccountNum;
                        nDXIntrastatDiffLine.CountryRegionIdVendPackingSlipTrans = nDXVendPackingSlipTrans.CountryRegionIdVendPackingSlipTrans;
                    }
                    nDXIntrastatDiffLine.ItemId            = vendInvoiceTrans.ItemId;
                    nDXIntrastatDiffLine.Jahr              = filterJahr;
                    nDXIntrastatDiffLine.Monat             = filterMonat;
                    nDXIntrastatDiffLine.PurchIdOrig       = vendInvoiceTrans.PurchID;
                    nDXIntrastatDiffLine.InvoiceId         = vendInvoiceTrans.InvoiceId;
                    nDXIntrastatDiffLine.Voucher           = taxTrans.Voucher;
                    nDXIntrastatDiffLine.DestCountryRegionId = vendInvoiceTrans.DestCountryRegionId;
                    nDXIntrastatDiffLine.ItemType          = inventTable.ItemType;
                    nDXIntrastatDiffLine.Intracode         = inventTable.Intracode;
                    nDXIntrastatDiffLine.IntraUnit         = EcoResCategoryIntrastat::findByCategoryId(EcoResCategory::find(inventTable.IntrastatCommodity).RecId).AdditionalUnits;
                    nDXIntrastatDiffLine.NetWeight         = inventTable.NetWeight;
                }

                nDXIntrastatDiffLine.AmountMST_TaxTrans    = vendInvoiceTrans.LineAmountMST;
                if (lInvoiceBase)
                {
                    nDXIntrastatDiffLine.Qty_TaxTrans          = vendInvoiceTrans.Qty;
                }
                else
                {
                    if (vendInvoiceTrans.Qty && (vendInvoiceTrans.Qty != nDXVendPackingSlipTrans.Qty))
                    {
                        nDXIntrastatDiffLine.AmountMST_TaxTrans    = (vendInvoiceTrans.LineAmountMST / vendInvoiceTrans.Qty) * nDXVendPackingSlipTrans.Qty  ;
                    }
                    nDXIntrastatDiffLine.Qty_TaxTrans          = nDXVendPackingSlipTrans.Qty;
                }
                nDXIntrastatDiffLine.InventTransId         = vendInvoiceTrans.InventTransId;
                ttsbegin;
                nDXIntrastatDiffLine.write();
                ttscommit;
            }
        }
    }

    // Ermittlung der Werte gemäß: taxTrans (die nicht in nDXIntrastatDiffLine ref. sind)
    q = new Query();
    q.allowCrossCompany(true);
    qbds = q.addDataSource(tablenum(TaxTrans));
    qbds.addRange(fieldnum(TaxTrans, TransDate)).value(SysQuery::range(filterFromDate, filterToDate));
    qbds.addRange(fieldnum(TaxTrans, InventTransId)).value(SysQuery::valueNotEmptyString());
    qbds.addRange(fieldnum(TaxTrans, TaxCode)).value(taxCode);

    qbds2 = qbds.addDataSource(tablenum(nDXIntrastatDiffLine));
    qbds2.joinMode(JoinMode::NoExistsJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.addLink(fieldnum(taxTrans, RecId), fieldnum(nDXIntrastatDiffLine, RefRecIdTaxTrans));

    qr = new QueryRun(q);
    while (qr.next())
    {
        taxTrans = qr.get(tablenum(TaxTrans));

        nDXIntrastatDiffLine.clear();
        nDXIntrastatDiffLine.RefCompanyId      = taxTrans.dataAreaId;
        nDXIntrastatDiffLine.RefRecIdTaxTrans  = taxTrans.RecId;
        nDXIntrastatDiffLine.Jahr              = filterJahr;
        nDXIntrastatDiffLine.Monat             = filterMonat;
        nDXIntrastatDiffLine.Voucher           = taxTrans.Voucher;
        nDXIntrastatDiffLine.AmountMST_TaxTrans    = taxTrans.TaxBaseAmount;
        ttsbegin;
        nDXIntrastatDiffLine.write();
        ttscommit;
    }


    // Ermittlung der Werte gemäß: IntraStat
    q = new Query();
    q.allowCrossCompany(true);
    qbds = q.addDataSource(tablenum(IntraStat));
    qbds.addRange(fieldnum(IntraStat, TransDate)).value(SysQuery::range(filterFromDate, filterToDate));
    qbds.addRange(fieldnum(IntraStat, DebCredType)).value(QueryValue(ModuleInventCustVend::Vend));

    qbds4 = qbds.addDataSource(tablenum(inventTable));
    qbds4.relations(true);
    qbds4.joinMode(JoinMode::InnerJoin);
    qbds4.fetchMode(QueryFetchMode::One2One);
    qr = new QueryRun(q);
    while (qr.next())
    {
        vendPackingSlipTrans = null;
        vendInvoiceTrans = null;
        intraStat = qr.get(tablenum(Intrastat));
        inventTable = qr.get(tablenum(InventTable));
        lVendInvoiceTrans = false;

        switch (intraStat.TransTableId)
        {
            case tablenum(VendInvoiceTrans)     :
                lVendInvoiceTrans = true;
                select firstonly crosscompany vendInvoiceTrans where vendInvoiceTrans.RecId == intraStat.TransRecId;
                select firstonly crosscompany nDXVendInvoiceTrans where nDXVendInvoiceTrans.RefRecIdVendInvoiceTrans == vendInvoiceTrans.RecId;

                break;
            case tablenum(VendPackingSlipTrans) :
                select firstonly crosscompany vendPackingSlipTrans where vendPackingSlipTrans.RecId == intraStat.TransRecId
                && vendPackingSlipTrans.dataAreaId == intraStat.dataAreaId;
                select firstonly crosscompany vendInvoiceTrans where vendInvoiceTrans.InvoiceId == intraStat.InvoiceId
                && vendInvoiceTrans.InventTransId == intraStat.InventTransId;

                select crosscompany count(recid) from nDXVendPackingSlipTrans where nDXVendPackingSlipTrans.RefRecIdVendPackingSlipTrans == vendPackingSlipTrans.RecId;
                if (nDXVendPackingSlipTrans.RecId > 1)
                {
                    Warning(strfmt("@NDX:NDXIntrastatWarningInvoiceRef", nDXVendPackingSlipTrans.RecId, vendInvoiceTrans.PurchID, vendInvoiceTrans.ItemId, vendInvoiceTrans.InventTransId));
                }
                select firstonly crosscompany nDXVendPackingSlipTrans where nDXVendPackingSlipTrans.RefRecIdVendPackingSlipTrans == vendPackingSlipTrans.RecId;

                break;
        }

        if((lVendInvoiceTrans && vendInvoiceTrans) || (!lVendInvoiceTrans && vendPackingSlipJour))
        {
            if (lVendInvoiceTrans)
            {
                select firstonly forUpdate nDXIntrastatDiffLine
                where   nDXIntrastatDiffLine.Jahr == filterJahr
                    &&  nDXIntrastatDiffLine.Monat == filterMonat
                    &&  nDXIntrastatDiffLine.RefRecIdVendInvoiceTrans == vendInvoiceTrans.RecId;
            }
            else
            {
                select firstonly forUpdate nDXIntrastatDiffLine
                where   nDXIntrastatDiffLine.Jahr == filterJahr
                    &&  nDXIntrastatDiffLine.Monat == filterMonat
                    &&  nDXIntrastatDiffLine.RefRecIdVendPackingSlipTrans == vendPackingSlipTrans.RecId;
            }
            if (!nDXIntrastatDiffLine)
            {
                nDXIntrastatDiffLine.RefCompanyId              = intraStat.dataAreaId;
                if (lVendInvoiceTrans)
                {
                    nDXIntrastatDiffLine.RefRecIdVendInvoiceTrans  = vendInvoiceTrans.RecId;
                    nDXIntrastatDiffLine.CountryRegionIdVendPackingSlipTrans = vendInvoiceTrans.DestCountryRegionId;
                }
                else
                {
                    nDXIntrastatDiffLine.RefRecIdVendPackingSlipTrans = vendPackingSlipTrans.RecId;
                    nDXIntrastatDiffLine.CountryRegionIdVendPackingSlipTrans = vendPackingSlipTrans.DestCountryRegionId;
                }
                nDXIntrastatDiffLine.ItemId                    = intraStat.ItemId;
                nDXIntrastatDiffLine.Jahr                      = filterJahr;
                nDXIntrastatDiffLine.Monat                     = filterMonat;
                nDXIntrastatDiffLine.InventTransId             = intraStat.InventTransId;
                nDXIntrastatDiffLine.InvoiceId                 = intraStat.InvoiceId;
                select firstonly crosscompany vendPackingSlipJour
                where   vendPackingSlipJour.dataAreaId == intraStat.dataAreaId
                    &&  vendPackingSlipJour.PackingSlipId == intraStat.PackingSlipId;
                if (vendPackingSlipJour)
                {
                    nDXIntrastatDiffLine.PurchIdOrig               = vendPackingSlipJour.PurchId;
                }
            }
            if (nDXIntrastatDiffLine.RefRecIdIntrastat)
            {
                Info(strFmt("@NDX:NDXIntrastatWarningExistingReference", nDXIntrastatDiffLine.RecId));
            }
            nDXIntrastatDiffLine.AmountMST_Intrastat   = intraStat.AmountMST * (intraStat.Direction == IntrastatDirection::Import ? 1 : -1);
            nDXIntrastatDiffLine.Qty_Intrastat         = intraStat.Qty * (intraStat.Direction == IntrastatDirection::Import ? 1 : -1);
            nDXIntrastatDiffLine.RefRecIdIntrastat     = intraStat.RecId;

            nDXIntrastatDiffLine.AccountNum            = intraStat.AccountNum;
            nDXIntrastatDiffLine.DestCountryRegionId   = intraStat.OrigCountryRegionId ? intraStat.OrigCountryRegionId : LogisticsPostalAddress::findByLocation(CompanyInfo::find().PrimaryAddressLocation).CountryRegionId;
            ttsbegin;
            nDXIntrastatDiffLine.write();
            ttscommit;
        }
        else
        {
            Warning(strFmt("@NDX:NDXIntrastatWarningVendInvoiceTransLocation", intraStat.RecId));
        }
    }

    // Differenzen prüfen
    while select forUpdate nDXIntrastatDiffLine
    where   nDXIntrastatDiffLine.Jahr == filterJahr
        &&  nDXIntrastatDiffLine.Monat == filterMonat
    {
        if ((decround(nDXIntrastatDiffLine.AmountMST_Intrastat,2) != decround(nDXIntrastatDiffLine.AmountMST_TaxTrans,2)) ||
        (decround(nDXIntrastatDiffLine.Qty_Intrastat,2) != decround(nDXIntrastatDiffLine.Qty_TaxTrans,2)))
        {
            nDXIntrastatDiffLine.IsDifference = true;
            ttsbegin;
            nDXIntrastatDiffLine.update();
            ttscommit;
        }

    }


    ttsbegin;
    nDXIntrastatDiff.write();
    ttscommit;
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
/// <param name = "_purchId">PurchId</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventTransId">InventTransId</param>
void initialize(PurchId _purchId = '', ItemId _itemId = '', InventTransId _inventTransId = '')
{
    NDXVendPackingSlipTrans    nDXVendPackingSlipTrans;
    NDXVendInvoiceTrans        nDXVendInvoiceTrans;
    ;
    if (!prmisdefault(_purchId))
    {
        purchId = _purchId;
    }
    if (!prmisdefault(_itemId))
    {
        itemId = _itemId;
    }
    if (!prmisdefault(_inventTransId))
    {
        inventTransId = _inventTransId;
    }

    delete_from nDXVendInvoiceTrans
    where nDXVendInvoiceTrans.OrigPurchId == purchId
        &&  nDXVendInvoiceTrans.ItemId == itemId
        &&  nDXVendInvoiceTrans.InventTransId == inventTransId;
    delete_from nDXVendPackingSlipTrans
    where nDXVendPackingSlipTrans.OrigPurchId == purchId
        &&  nDXVendPackingSlipTrans.ItemId == itemId
        &&  nDXVendPackingSlipTrans.InventTransId == inventTransId;
}

