/// DebuC 30.03.23
/// </summary>
/// <param name = "qbr">QueryBuildRange</param>
void setDateRange2qbr(QueryBuildRange qbr)
{
    qbr.value(SysQuery::range(filterFromDate, filterToDate));
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
/// <param name = "iMonth">int</param>
/// <param name = "iYear">int</param>
void setFilterDate(int iMonth, int iYear)
{
    ;
    filterMonat = iMonth;
    filterJahr  = iYear;
    [filterFromDate,
 filterToDate] = NDXHelperDate::firstAndLastDayOfMonth(iMonth, iYear);
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
/// <param name = "qbr">QueryBuildRange</param>
void setTaxCodeQbr(QueryBuildRange qbr)
{
    ;
    if (taxCode && taxCode2)
    {
        qbr.value(strfmt('((%1 == "%2") || (%1 == "%3"))', fieldid2name(tablenum(TaxTrans), fieldnum(TaxTrans, TaxCode)),taxCode, taxCode2));
    }
    else
    {
        qbr.value(taxCode);
    }
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
void VendInvoiceTrans4PurchLineItem()
{
    VendInvoiceTrans        vendInvoiceTrans;
    PurchLine               purchLine;
    VendInvoiceJour         vendInvoiceJour;
    NDXVendInvoiceTrans    nDXVendInvoiceTrans;

    Query       q = new Query();
    QueryRun    qr;
    QueryBuildDataSource    qbds1, qbds2, qbds3, qbds4, qbds5, qbds6;
    QueryBuildFieldList     fields1, fields2, fields5, fields6;

    ;
    qbds1 = q.addDataSource(tablenum(PurchTable));
    qbds1.addRange(fieldnum(PurchTable, PurchId)).value(purchId);
    fields1 = qbds1.fields();
    fields1.addField(fieldnum(PurchTable, PurchId));

    qbds2 = qbds1.addDataSource(tablenum(PurchLine));
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.relations(true);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.addRange(fieldnum(PurchLine, ItemId)).value(itemId);
    qbds2.addRange(fieldnum(PurchLine, InventTransId)).value(inventTransId);
    fields2 = qbds2.fields();
    fields2.addField(fieldnum(PurchLine, ItemId));

    qbds3 = qbds1.addDataSource(tablenum(VendInvoicePurchLink));
    qbds3.joinMode(JoinMode::ExistsJoin);
    qbds3.relations(true);
    qbds3.fetchMode(QueryFetchMode::One2One);

    qbds4 = qbds3.addDataSource(tablenum(VendInvoiceJour));
    qbds4.joinMode(JoinMode::ExistsJoin);
    qbds4.relations(true);
    qbds4.fetchMode(QueryFetchMode::One2One);

    qbds5 = qbds4.addDataSource(tablenum(VendInvoiceTrans));
    qbds5.joinMode(JoinMode::InnerJoin);
    qbds5.relations(true);
    qbds5.fetchMode(QueryFetchMode::One2One);
    fields5 = qbds5.fields();
    fields5.addField(fieldnum(VendInvoiceTrans, Qty));

    qbds6 = qbds2.addDataSource(tablenum(VendInvoiceTrans));
    qbds6.joinMode(JoinMode::InnerJoin);
    qbds6.addLink(fieldnum(PurchLine, ItemId), fieldnum(VendInvoiceTrans, ItemId));
    qbds6.addLink(fieldnum(PurchLine, InventTransId), fieldnum(VendInvoiceTrans, InventTransId));
    qbds6.fetchMode(QueryFetchMode::One2One);
    fields6 = qbds6.fields();
    fields6.addField(fieldnum(VendInvoiceTrans, Qty));
    fields6.addField(fieldnum(VendInvoiceTrans, OrigPurchId));
    fields6.addField(fieldnum(VendInvoiceTrans, InvoiceDate));
    fields6.addField(fieldnum(VendInvoiceTrans, InternalInvoiceId));
    fields6.addField(fieldnum(VendInvoiceTrans, ItemId));
    fields6.addField(fieldnum(VendInvoiceTrans, InventTransId));
    fields6.addField(fieldnum(VendInvoiceTrans, InvoiceId));
    fields6.addField(fieldnum(VendInvoiceTrans, DestCountryRegionId));

    qr = new QueryRun(q);
    RecordInsertList ndxVendInvoiceTransIL = new RecordInsertList(tableNum(NDXVendInvoiceTrans));
    while (qr.next())
    {
        if (qr.changed(tablenum(VendInvoiceTrans), 1))
        {
            vendInvoiceTrans = qr.get(tablenum(VendInvoiceTrans), 1);
        }
        if (qr.changed(tablenum(PurchLine)))
        {
            purchLine = qr.get(tablenum(PurchLine));
        }

        vendInvoiceJour = VendInvoiceJour::findFromVendInvoiceTrans(vendInvoiceTrans.OrigPurchId, vendInvoiceTrans.InvoiceId, vendInvoiceTrans.InvoiceDate, vendInvoiceTrans.numberSequenceGroup, vendInvoiceTrans.InternalInvoiceId);

        nDXVendInvoiceTrans.clear();
        nDXVendInvoiceTrans.OrigPurchId        = vendInvoiceTrans.OrigPurchId;
        nDXVendInvoiceTrans.InvoiceDate        = vendInvoiceTrans.InvoiceDate;
        nDXVendInvoiceTrans.InternalInvoiceId  = vendInvoiceTrans.InternalInvoiceId;
        nDXVendInvoiceTrans.ItemId             = vendInvoiceTrans.ItemId;
        nDXVendInvoiceTrans.InventTransId      = vendInvoiceTrans.InventTransId;
        nDXVendInvoiceTrans.Qty                = vendInvoiceTrans.Qty;
        nDXVendInvoiceTrans.CountryRegionIdVendInvoiceTrans = vendInvoiceTrans.DestCountryRegionId;
        nDXVendInvoiceTrans.RefRecIdVendInvoiceTrans   = vendInvoiceTrans.RecId;
        nDXVendInvoiceTrans.AccountNum         = vendInvoiceJour.InvoiceAccount;
        ndxVendInvoiceTransIL.add(NDXVendInvoiceTrans);
    }
    ndxVendInvoiceTransIL.insertDatabase();
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
void VendPackingSlip2VendInvoice()
{
    NDXVendPackingSlipTrans        nDXVendPackingSlipTrans;
    NDXVendInvoiceTrans            nDXVendInvoiceTrans;
    Qty                             qty;
    container                       conRec, conCheckRec;
    container                       conCheckPossible;
    int                             i, j;
    recId                           recId, recIdCheck;
    boolean                         lOK;

    int     value;
    ;
    ttsbegin;
    // alle Rechnungspositionen durchlaufen
    while select forUpdate nDXVendInvoiceTrans
    where        nDXVendInvoiceTrans.OrigPurchId == purchId
        &&       nDXVendInvoiceTrans.ItemId  == itemId
        &&       nDXVendInvoiceTrans.InventTransId == inventTransId
    {
        conRec = connull();
        conCheckRec = connull();
        qty     = 0;
        lOK     = false;
        // alle Lieferscheinpositionen durchlaufen
        while select forUpdate nDXVendPackingSlipTrans
        order by nDXVendPackingSlipTrans.Qty desc
        where       nDXVendPackingSlipTrans.OrigPurchId == purchId
            &&      nDXVendPackingSlipTrans.ItemId  == itemId
            &&      nDXVendPackingSlipTrans.InventTransId == inventTransId
            &&      nDXVendPackingSlipTrans.Assigned == NoYes::No
        {
            conCheckRec += nDXVendPackingSlipTrans.RecId;
        }
        conCheckPossible = nDXIntrastat::getPossibleLSCombinations(conlen(conCheckRec));   // Ermittlung der möglichen LS-Kombinationen
        for (i=1; i<=conlen(conCheckPossible); i++)         // Iteration über alle möglichen LS-Kombinationen
        {
            conRec  = connull();
            qty     = 0;
            lOK     = false;
            value   = conpeek(conCheckPossible, i);
            for (j=1; j<=conlen(conCheckRec); j++)   // Durchlauf der LS-Positionen
            {
                if (value & (1 << j))   // in Prüfung einbeziehen
                {
                    recIdCheck = conpeek(conCheckRec, j);
                    select firstonly nDXVendPackingSlipTrans where nDXVendPackingSlipTrans.RecId == recIdCheck;
                    qty += nDXVendPackingSlipTrans.Qty;
                    lOK = (qty == nDXVendInvoiceTrans.Qty);
                    conRec += nDXVendPackingSlipTrans.RecId;
                    if (lOK)
                    {
                        break;
                    }
                }
            }
            if (lOK)
            {
                break;
            }

        }

        if (lOK)    // alle LS-Positionen konnten der Rechnungsposition zugeordnet werden
        {
            for (i=1; i<=conlen(conRec); i++)
            {
                recId = conpeek(conRec, i);
                select firstonly forUpdate nDXVendPackingSlipTrans where nDXVendPackingSlipTrans.RecId == recId;
                nDXVendPackingSlipTrans.RefRecIdVendInvoiceTrans = nDXVendInvoiceTrans.RefRecIdVendInvoiceTrans;
                nDXVendPackingSlipTrans.Assigned = NoYes::Yes;
                nDXVendPackingSlipTrans.update();
            }
            nDXVendInvoiceTrans.QtyPackingSlipTrans = qty;
            nDXVendInvoiceTrans.update();
        }
    }
    ttscommit;
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
void VendPackingSlipTrans4PurchLineItem()
{
    VendPackingSlipTrans        vendPackingSlipTrans;
    VendPackingSlipJour         vendPackingSlipJour;
    PurchLine                   purchLine;
    NDXVendPackingSlipTrans    nDXVendPackingSlipTrans;

    Query       q = new Query();
    QueryRun    qr;
    QueryBuildDataSource    qbds1, qbds2, qbds3, qbds4, qbds5, qbds6;
    QueryBuildFieldList     fields1, fields2, fields5, fields6;

    ;
    qbds1 = q.addDataSource(tablenum(PurchTable));
    qbds1.addRange(fieldnum(PurchTable, PurchId)).value(purchId);
    fields1 = qbds1.fields();
    fields1.addField(fieldnum(PurchTable, PurchId));

    qbds2 = qbds1.addDataSource(tablenum(PurchLine));
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.relations(true);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.addRange(fieldnum(PurchLine, ItemId)).value(itemId);
    qbds2.addRange(fieldnum(PurchLine, InventTransId)).value(inventTransId);
    fields2 = qbds2.fields();
    fields2.addField(fieldnum(PurchLine, ItemId));

    qbds3 = qbds1.addDataSource(tablenum(VendPackingSlipPurchLink));
    qbds3.joinMode(JoinMode::ExistsJoin);
    qbds3.relations(true);
    qbds3.fetchMode(QueryFetchMode::One2One);

    qbds4 = qbds3.addDataSource(tablenum(VendPackingSlipJour));
    qbds4.joinMode(JoinMode::ExistsJoin);
    qbds4.relations(true);
    qbds4.fetchMode(QueryFetchMode::One2One);

    qbds5 = qbds4.addDataSource(tablenum(VendPackingSlipTrans));
    qbds5.joinMode(JoinMode::InnerJoin);
    qbds5.relations(true);
    qbds5.fetchMode(QueryFetchMode::One2One);
    fields5 = qbds5.fields();
    fields5.addField(fieldnum(VendPackingSlipTrans, Qty));
    fields5.addField(fieldNum(VendPackingSlipJour, PurchId));

    qbds6 = qbds2.addDataSource(tablenum(VendPackingSlipTrans));
    qbds6.joinMode(JoinMode::InnerJoin);
    qbds6.addLink(fieldnum(PurchLine, ItemId), fieldnum(VendPackingSlipTrans, ItemId));
    qbds6.addLink(fieldnum(PurchLine, InventTransId), fieldnum(VendPackingSlipTrans, InventTransId));
    qbds6.fetchMode(QueryFetchMode::One2One);
    fields6 = qbds6.fields();
    fields6.addField(fieldnum(VendPackingSlipTrans, Qty));
    fields6.addField(fieldnum(VendPackingSlipTrans, ItemId));
    fields6.addField(fieldnum(VendPackingSlipTrans, InventTransId));
    fields6.addField(fieldnum(VendPackingSlipTrans, DeliveryDate));
    fields6.addField(fieldnum(VendPackingSlipTrans, OrigPurchid));
    fields6.addField(fieldnum(VendPackingSlipTrans, Qty));
    fields6.addField(fieldnum(VendPackingSlipTrans, DestCountryRegionId));
    fields6.addField(fieldnum(VendPackingSlipTrans, PackingSlipId));

    qr = new QueryRun(q);
    RecordInsertList nDXVendPackingSlipTransIL = new RecordInsertList(tableNum(NDXVendPackingSlipTrans));
    while (qr.next())
    {
        if (qr.changed(tablenum(VendPackingSlipTrans), 1))
        {
            vendPackingSlipTrans = qr.get(tablenum(VendPackingSlipTrans), 1);
        }

        if (qr.changed(tablenum(PurchLine)))
        {
            purchLine = qr.get(tablenum(PurchLine));
        }

        vendPackingSlipJour = vendPackingSlipJour::findRecId(vendPackingSlipTrans.vendPackingslipJour);

        nDXVendPackingSlipTrans.clear();
        nDXVendPackingSlipTrans.InventTransId          = vendPackingSlipTrans.InventTransId;
        nDXVendPackingSlipTrans.ItemId                 = vendPackingSlipTrans.ItemId;
        nDXVendPackingSlipTrans.DeliveryDate           = vendPackingSlipTrans.DeliveryDate;
        nDXVendPackingSlipTrans.OrigPurchid            = vendPackingSlipTrans.OrigPurchid;
        nDXVendPackingSlipTrans.Qty                    = vendPackingSlipTrans.Qty;
        nDXVendPackingSlipTrans.RefRecIdVendPackingSlipTrans   = vendPackingSlipTrans.RecId;
        nDXVendPackingSlipTrans.CountryRegionIdVendPackingSlipTrans   = vendPackingSlipTrans.DestCountryRegionId;
        nDXVendPackingSlipTrans.AccountNum             = vendPackingSlipJour.InvoiceAccount;
        nDXVendPackingSlipTransIL.add(nDXVendPackingSlipTrans);
    }
    nDXVendPackingSlipTransIL.insertDatabase();
}

/// <summary>
/// DebuC 30.03.23
/// </summary>
/// <param name = "level">int</param>
/// <returns>container</returns>
static container getPossibleLSCombinations(int level)
{
    container conCheck = connull();
    container conC1;
    container conChecked = connull();
    int i, j, k, l, iCheck, iNotCheck;
    int checkV, checkV1, checkV2, checkV3, checkV4;
    int checkVNot;
    int conLen1;
    ;
    for (i=1; i<=level; i++)
    {
        conCheck += 1 << i;
    }

    conLen1 = conlen(conCheck);

    for (l=1; l <= conLen1; l++)
    {
        iCheck    = l + 1;
        iNotCheck = l + 2;
        conc1 = connull();
        checkV2 = 0;
        checkVNot = 0;
        while (true)
        {
            checkV1 = conpeek(conCheck,l);
            for (j=l+1; j<=conlen(conCheck); j++)
            {
                checkV = checkV1;
                checkV += checkV2;
                checkV3 = conpeek(conCheck,j);
                for (k=j; k<= conLen1; k++)
                {
                    checkV4 = conpeek(conCheck,k);
                    if (checkV4 == checkV2)
                    {
                        continue;
                    }
                    if (confind(conc1, checkV4))
                    {                    
                        continue;
                    }
                    checkV += checkV4;
                }
                if (!confind(conChecked, checkV))
                {
                    conChecked += checkV;
                }
            }
            if (iNotCheck >= conLen1)
            {
                break;
            }
            checkV2       = conpeek(conCheck, iCheck);
            checkVNot     = conpeek(conCheck, iNotCheck);
            conc1 += checkV2;
            ++iCheck;
            ++iNotCheck;
        }
    }
    conChecked += conpeek(conCheck, conLen1);
    return conChecked;
}

