/// <summary>
/// DebuC 30.03.23
/// </summary>
/// <param name = "recId">recId</param>
/// <returns>VendInvoiceJour</returns>
static VendInvoiceJour vendInvoiceJourFromRecIdVendInvoiceTrans(recId recId)
{
    VendInvoiceJour vendInvoiceJour;
    VendInvoiceTrans    vendInvoiceTrans;
    ;
    if (recId)
    {
        select firstonly vendInvoiceTrans where vendInvoiceTrans.RecId == recId;
    }
    if (vendInvoiceTrans.RecId)
    {
        select firstonly vendInvoiceJour
            where vendInvoiceJour.PurchId == VendInvoiceTrans.PurchID;
    }

    return vendInvoiceJour;
}
